/**
 * Aapki Nazar - Genuine OWASP Core Rule Set (CRS) Audit Log Ingestion Service
 * 
 * Monitors the ModSecurity JSON audit log generated by the official OWASP CRS Nginx container.
 * Features:
 *  - Continuous byte-offset tailing with incomplete line buffering (resilient to partial writes & chunking).
 *  - File truncation / log rotation detection.
 *  - Transaction deduplication with post-persistence state commitment.
 *  - Protocol warning vs exploit attack discrimination (strict incident creation policy).
 *  - Separation of Gateway health vs Ingestion health.
 *  - Sensitive data sanitization and non-fabrication of vulnerability claims.
 */

const fs = require("fs");
const path = require("path");
const http = require("http");
const localDb = require("./localDbService");
const incidentService = require("./incidentService");
const attackCorrelationService = require("./attackCorrelationService");

class CrsIngestionService {
  constructor() {
    this.logPath = process.env.CRS_AUDIT_LOG_PATH || path.join(__dirname, "../../waf-logs/audit.log");
    this.lastOffset = 0;
    this.isPolling = false;
    this.pollInterval = null;
    this.io = null;
    this.processedTxIds = new Set();
    
    // Gateway health status (actively probed, not inferred solely from audit.log)
    this.gatewayHealth = {
      status: "UNKNOWN",
      url: "http://localhost:8080",
      isVerifiedGateway: false,
      serverHeader: null,
      lastChecked: null,
      latencyMs: null,
      error: null
    };

    // Ingestion stream status
    this.ingestionStatus = {
      active: false,
      logPath: this.logPath,
      lastReadTimestamp: null,
      totalIngested: 0,
      totalBlocked: 0,
      totalAllowed: 0,
      quarantinedCount: 0,
      stalled: false,
      lastError: null
    };
  }

  setIo(io) {
    this.io = io;
    if (attackCorrelationService) attackCorrelationService.setIo(io);
  }

  /**
   * Start the ingestion monitor & recurring gateway health check
   */
  start(ioInstance = null, intervalMs = 1000) {
    if (ioInstance) {
      this.io = ioInstance;
      if (attackCorrelationService) attackCorrelationService.setIo(ioInstance);
    }
    if (this.isPolling) return;

    this.isPolling = true;
    this.ingestionStatus.active = true;
    console.log(`[CRS-INGESTION] Monitoring genuine OWASP CRS audit log at: ${this.logPath}`);

    // Initial offset determination
    if (fs.existsSync(this.logPath)) {
      try {
        // Read from beginning to ensure existing records are in SQLite
        this.lastOffset = 0;
      } catch (e) {
        this.lastOffset = 0;
      }
    }

    // Run initial checks
    this.pollLog();
    this.checkGatewayHealth();

    // Recurring poll
    this.pollInterval = setInterval(() => {
      this.pollLog();
    }, intervalMs);

    // Gateway health check every 5 seconds
    this.healthInterval = setInterval(() => {
      this.checkGatewayHealth();
    }, 5000);
  }

  /**
   * Stop the ingestion monitor
   */
  stop() {
    if (this.pollInterval) {
      clearInterval(this.pollInterval);
      this.pollInterval = null;
    }
    if (this.healthInterval) {
      clearInterval(this.healthInterval);
      this.healthInterval = null;
    }
    this.isPolling = false;
    this.ingestionStatus.active = false;
    console.log("[CRS-INGESTION] Monitor stopped.");
  }

  /**
   * Check actual gateway connectivity and verify expected service identity.
   * Ensures unrelated services on port 8080 (including foreign Nginx servers)
   * are not falsely identified as the Aapki Nazar CRS gateway.
   */
  async checkGatewayHealth(customPort = null) {
    const targetPort = customPort || parseInt(process.env.CRS_GATEWAY_PORT, 10) || 8080;
    const targetHost = process.env.CRS_GATEWAY_HOST || "127.0.0.1";

    return new Promise((resolve) => {
      const startTime = Date.now();
      const req = http.request({
        hostname: targetHost,
        port: targetPort,
        path: "/health",
        method: "GET",
        timeout: 2500
      }, (res) => {
        let body = "";
        res.on("data", chunk => { body += chunk; });
        res.on("end", () => {
          const latencyMs = Date.now() - startTime;
          const serverHeader = (res.headers["server"] || "").toLowerCase();
          const protectedBy = (res.headers["x-protected-by"] || "").toLowerCase();
          const backendServer = res.headers["x-backend-server"] || "";

          // Strict Gateway & Protected Application verification:
          // 1. Upstream reverse proxy must be Nginx.
          // 2. Protected backend application must return its explicit identity marker:
          //    X-Backend-Server: Aapki-Nazar-Protected-App/1.0
          //    X-Protected-By: OWASP-CRS-ModSecurity
          // A foreign or unrelated Nginx server lacking these markers MUST be rejected.
          const isNginx = serverHeader.startsWith("nginx");
          const isExpectedApp = (backendServer === "Aapki-Nazar-Protected-App/1.0" || backendServer.includes("Aapki-Nazar")) &&
                                protectedBy.includes("owasp-crs");

          if (isNginx && isExpectedApp && res.statusCode === 200) {
            this.gatewayHealth = {
              status: "ONLINE",
              url: `http://${targetHost}:${targetPort}`,
              isVerifiedGateway: true,
              serverHeader: res.headers["server"] || "nginx",
              backendReachable: true,
              httpStatus: res.statusCode,
              latencyMs,
              lastChecked: new Date().toISOString(),
              error: null
            };
          } else if (isNginx && (res.statusCode === 502 || res.statusCode === 504)) {
            // Nginx gateway is alive, but protected demo app container is unreachable
            this.gatewayHealth = {
              status: "GATEWAY_UP_BACKEND_UNREACHABLE",
              url: `http://${targetHost}:${targetPort}`,
              isVerifiedGateway: true,
              serverHeader: res.headers["server"] || "nginx",
              backendReachable: false,
              httpStatus: res.statusCode,
              latencyMs,
              lastChecked: new Date().toISOString(),
              error: `Nginx gateway is active, but protected demo app is unreachable (HTTP ${res.statusCode}).`
            };
          } else {
            // Unrelated service, foreign Nginx, or missing application identity marker
            this.gatewayHealth = {
              status: "UNRECOGNIZED_SERVICE",
              url: `http://${targetHost}:${targetPort}`,
              isVerifiedGateway: false,
              serverHeader: res.headers["server"] || "unknown",
              backendReachable: false,
              httpStatus: res.statusCode,
              latencyMs,
              lastChecked: new Date().toISOString(),
              error: `Port ${targetPort} responded, but expected backend application identity (X-Backend-Server: Aapki-Nazar-Protected-App/1.0) is missing.`
            };
          }
          resolve(this.gatewayHealth);
        });
      });

      req.on("error", (err) => {
        this.gatewayHealth = {
          status: "OFFLINE",
          url: `http://${targetHost}:${targetPort}`,
          isVerifiedGateway: false,
          serverHeader: null,
          backendReachable: false,
          httpStatus: null,
          latencyMs: null,
          lastChecked: new Date().toISOString(),
          error: `Connection failed: ${err.message}`
        };
        resolve(this.gatewayHealth);
      });

      req.on("timeout", () => {
        req.destroy();
        this.gatewayHealth = {
          status: "OFFLINE",
          url: `http://${targetHost}:${targetPort}`,
          isVerifiedGateway: false,
          serverHeader: null,
          backendReachable: false,
          httpStatus: null,
          latencyMs: null,
          lastChecked: new Date().toISOString(),
          error: "Connection timed out after 2500ms"
        };
        resolve(this.gatewayHealth);
      });

      req.end();
    });
  }

  /**
   * Poll log file for new entries with resilient boundary alignment and
   * record-by-record committed offset tracking.
   * Handles:
   * - Partial JSON writes (only decodes up to complete newline boundary).
   * - File truncation / replacement (detects size reduction or inode/birthtime change).
   * - Safe retry on SQLite persistence errors (does NOT advance offset past failed record).
   * - Bounded retry limit (5) preventing indefinite stalling on corrupt lines.
   */
  async pollLog() {
    if (!fs.existsSync(this.logPath)) {
      this.ingestionStatus.active = false;
      return;
    }

    try {
      const stats = fs.statSync(this.logPath);
      this.ingestionStatus.active = true;

      // Handle file rotation or truncation (size reduction or inode/birthtime change)
      const isFileReplaced = (this.lastFileIno && stats.ino && this.lastFileIno !== stats.ino) ||
                             (this.lastFileBirthtime && stats.birthtimeMs && stats.birthtimeMs > this.lastFileBirthtime);
      if (stats.size < this.lastOffset || isFileReplaced) {
        console.log(`[CRS-INGESTION] Audit log truncated or rotated (old offset: ${this.lastOffset}, new size: ${stats.size}). Resetting offset.`);
        this.lastOffset = 0;
        this.lastFileIno = stats.ino;
        this.lastFileBirthtime = stats.birthtimeMs;
      }

      if (stats.size === this.lastOffset) {
        // No new data
        return;
      }

      const bytesToRead = stats.size - this.lastOffset;
      const buffer = Buffer.alloc(bytesToRead);

      const fd = fs.openSync(this.logPath, "r");
      try {
        fs.readSync(fd, buffer, 0, bytesToRead, this.lastOffset);
      } finally {
        fs.closeSync(fd);
      }

      // Find the last complete newline in the newly read chunk
      const lastNewlineIndex = buffer.lastIndexOf(10); // 0x0A = '\n'

      // If no newline is present in the chunk, the line is still being written.
      // Wait for the next poll without advancing the offset.
      if (lastNewlineIndex === -1) {
        return;
      }

      // Only iterate up to the last complete newline boundary
      const completeBuffer = buffer.subarray(0, lastNewlineIndex + 1);

      let currentBytePos = 0;
      while (currentBytePos < completeBuffer.length) {
        const nextNewline = completeBuffer.indexOf(10, currentBytePos);
        if (nextNewline === -1) break;

        const lineBuffer = completeBuffer.subarray(currentBytePos, nextNewline);
        const lineBytes = (nextNewline - currentBytePos) + 1; // includes the \n byte
        const lineStr = lineBuffer.toString("utf8").trim();

        if (lineStr.length > 0 && lineStr.startsWith("{")) {
          try {
            await this.processAuditRecord(lineStr);
            // Succeeded (or safely quarantined): advance committed offset past this record
            this.lastOffset += lineBytes;
            this.consecutiveFailures = 0;
            this.ingestionStatus.stalled = false;
          } catch (err) {
            this.consecutiveFailures = (this.consecutiveFailures || 0) + 1;
            this.ingestionStatus.stalled = true;
            this.ingestionStatus.lastError = `Persistence error at offset ${this.lastOffset}: ${err.message}`;
            console.warn(`[CRS-INGESTION] Storage/database failure at offset ${this.lastOffset} (attempt ${this.consecutiveFailures}): ${err.message}. Retaining offset for retry.`);
            // Stop processing this chunk and retry on next poll without advancing offset!
            return;
          }
        } else {
          // Non-JSON or empty line: advance past it
          this.lastOffset += lineBytes;
        }

        currentBytePos = nextNewline + 1;
      }
    } catch (err) {
      this.ingestionStatus.lastError = err.message;
      console.error("[CRS-INGESTION] Error polling audit log:", err.message);
    }
  }

  /**
   * Parse and process a single ModSecurity JSON audit record
   */
  async processAuditRecord(jsonStr) {
    if (!jsonStr || !jsonStr.startsWith("{")) return null;

    let parsed = null;
    try {
      parsed = JSON.parse(jsonStr);
    } catch (e) {
      // Incomplete write or invalid JSON: quarantine if complete line
      console.warn(`[CRS-INGESTION] Quarantining malformed JSON at offset ${this.lastOffset}: ${e.message}`);
      try {
        await localDb.quarantineRecord({
          rawRecord: jsonStr,
          reason: `Malformed JSON: ${e.message}`,
          offset: this.lastOffset
        });
      } catch (qErr) {}
      this.ingestionStatus.quarantinedCount = (this.ingestionStatus.quarantinedCount || 0) + 1;
      return null;
    }

    const tx = parsed.transaction;
    if (!tx || !tx.unique_id) return null;

    const txId = String(tx.unique_id);

    // In-memory deduplication check
    if (this.processedTxIds.has(txId)) return null;

    // Database deduplication check with missing correlation recovery
    const existing = await localDb.getWafEventByTransactionId(txId);
    if (existing) {
      this.processedTxIds.add(txId);
      // Recovery Check: Was this event eligible, but its correlation step failed previously?
      if (localDb.isEventEligible(existing)) {
        const existingLink = await localDb.getCampaignByWafEventId(existing.id || existing.transactionId);
        if (!existingLink) {
          console.log(`[CRS-INGESTION] Recovering missing campaign correlation for eligible event ${existing.transactionId}`);
          try {
            await attackCorrelationService.processEvent(existing);
            if (this.ingestionStatus.pendingRecoveryCount > 0) {
              this.ingestionStatus.pendingRecoveryCount--;
            }
          } catch (recErr) {
            console.error("[CRS-INGESTION] Recovery correlation failed:", recErr.message);
          }
        }
      }
      return existing;
    }

    // Normalize transaction
    const normalized = this.normalizeTransaction(tx);

    // Persist WAF event into SQLite (let errors throw so pollLog catches them and avoids advancing offset)
    const createdEvent = await localDb.createWafEvent(normalized);

    // Mark as processed in-memory AFTER persistence succeeds
    this.processedTxIds.add(txId);
    if (this.processedTxIds.size > 10000) {
      const first = this.processedTxIds.values().next().value;
      this.processedTxIds.delete(first);
    }

    this.ingestionStatus.totalIngested++;
    this.ingestionStatus.lastReadTimestamp = new Date().toISOString();

    if (normalized.blocked) {
      this.ingestionStatus.totalBlocked++;
    } else {
      this.ingestionStatus.totalAllowed++;
    }

    // ─────────────────────────────────────────────────────────────────
    // INCIDENT CREATION POLICY (Phase 1):
    // 1. Observed WAF events are always stored in waf_events.
    // 2. An incident is ONLY created if:
    //    a. The transaction was actively BLOCKED by WAF (HTTP 403 / rule 949110), OR
    //    b. Anomaly score >= 5 AND primary rule is an active exploit family
    //       (SQLi 942, XSS 941, RCE 932, LFI 930, RFI 931, SSRF 934, Log4j 944, Scanner 913).
    // 3. Low-severity protocol warnings (e.g. 920350: numeric IP Host header)
    //    on allowed requests (HTTP 200) DO NOT create incidents.
    // ─────────────────────────────────────────────────────────────────
    const isAttackFamily = normalized.primaryRuleId && (
      normalized.primaryRuleId.startsWith("OWASP-CRS-942") || // SQLi
      normalized.primaryRuleId.startsWith("OWASP-CRS-941") || // XSS
      normalized.primaryRuleId.startsWith("OWASP-CRS-932") || // RCE
      normalized.primaryRuleId.startsWith("OWASP-CRS-930") || // LFI
      normalized.primaryRuleId.startsWith("OWASP-CRS-931") || // RFI
      normalized.primaryRuleId.startsWith("OWASP-CRS-934") || // SSRF
      normalized.primaryRuleId.startsWith("OWASP-CRS-944") || // Log4j / Java
      normalized.primaryRuleId.startsWith("OWASP-CRS-913")    // Scanner
    );

    const shouldCreateIncident = normalized.blocked || (normalized.anomalyScore >= 5 && isAttackFamily);

    let incident = null;
    if (shouldCreateIncident) {
      incident = await this.dispatchCrsIncident(normalized, createdEvent);
      if (incident && incident.incidentId) {
        await localDb.linkWafEventToIncident(txId, incident.incidentId);
        createdEvent.incidentId = incident.incidentId;
      }
    }

    // Correlate into Phase 2 Attack Campaigns
    try {
      await attackCorrelationService.processEvent(createdEvent);
    } catch (corrErr) {
      console.error("[CRS-INGESTION] Campaign correlation error (recoverable):", corrErr.message);
      this.ingestionStatus.pendingRecovery = true;
      this.ingestionStatus.pendingRecoveryCount = (this.ingestionStatus.pendingRecoveryCount || 0) + 1;
    }

    // Real-time broadcast via Socket.IO
    if (this.io) {
      // 1. Unified crs_waf_event payload (flat, robust contract)
      this.io.emit("crs_waf_event", {
        transactionId: normalized.transactionId,
        timestamp: normalized.timestamp,
        clientIp: normalized.clientIp,
        simulatedClientIp: normalized.simulatedClientIp,
        method: normalized.method,
        uri: normalized.uri,
        httpCode: normalized.httpCode,
        statusCode: normalized.httpCode,
        action: normalized.action,
        blocked: normalized.blocked,
        anomalyScore: normalized.anomalyScore,
        primaryRuleId: normalized.primaryRuleId,
        primaryRuleMsg: normalized.primaryRuleMsg,
        category: normalized.category,
        severity: normalized.severity,
        incidentId: incident ? incident.incidentId : null,
        incidentCreated: !!incident,
        eventSource: "OFFICIAL_CRS"
      });

      // 2. Real-time Telemetry Stream
      const color = normalized.blocked ? "#dc2626" : (normalized.anomalyScore >= 5 ? "#f59e0b" : "#10b981");
      const label = normalized.blocked ? "[OFFICIAL CRS BLOCKED]" : (normalized.anomalyScore >= 5 ? "[OFFICIAL CRS ALERT]" : "[OFFICIAL CRS PASSED]");

      const ipDisplay = normalized.simulatedClientIp 
        ? `${normalized.clientIp} [Sim: ${normalized.simulatedClientIp}]`
        : normalized.clientIp;

      this.io.emit("telemetry_stream", {
        id: `crs-${Date.now()}-${txId.substring(0, 8)}`,
        timestamp: normalized.timestamp,
        raw: `${label} HTTP ${normalized.httpCode} ${normalized.method} ${normalized.uri} (Score: ${normalized.anomalyScore}) — ${normalized.primaryRuleMsg || 'Transaction Inspected'}`,
        sensor: "OFFICIAL-OWASP-CRS",
        sourceIp: ipDisplay,
        isThreat: shouldCreateIncident,
        threatType: normalized.category || "OWASP CRS Detection",
        threatScore: Math.min(100, Math.max(0, normalized.anomalyScore * 5 || (normalized.blocked ? 85 : 0))),
        severity: normalized.severity,
        color,
        wafTransactionId: txId,
        ruleId: normalized.primaryRuleId
      });
    }

    return createdEvent;
  }

  /**
   * Normalize ModSecurity v3 transaction into structured security event
   */
  normalizeTransaction(tx) {
    // Real network socket client IP
    const socketClientIp = tx.client_ip || "127.0.0.1";
    
    // Check for simulated client IP & session from explicit simulation headers
    let simulatedClientIp = null;
    let simulatedSessionId = null;
    const reqHeaders = tx.request?.headers || {};
    for (const [k, v] of Object.entries(reqHeaders)) {
      const lowerK = k.toLowerCase();
      if (lowerK === "x-simulation-ip") {
        simulatedClientIp = String(v).split(",")[0].trim();
      } else if (lowerK === "x-simulation-session") {
        simulatedSessionId = String(v).split(",")[0].trim();
      }
    }

    const httpCode = tx.response?.http_code || 200;
    const isBlocked = !!(tx.is_interrupted || httpCode === 403);
    const action = isBlocked ? "BLOCKED" : "ALLOWED";

    const messages = tx.messages || [];
    let anomalyScore = 0;
    let primaryRule = null;
    const allTags = new Set();

    // Select candidate attack rules
    const candidateRules = [];
    for (const msg of messages) {
      const details = msg.details || {};
      const ruleId = String(details.ruleId || "");
      const text = msg.message || "";

      // Aggregate tags
      if (Array.isArray(details.tags)) {
        details.tags.forEach(t => allTags.add(t));
      }

      // Check for anomaly score evaluation rule 949110
      if (ruleId === "949110" || text.includes("Inbound Anomaly Score Exceeded")) {
        const scoreMatch = text.match(/Total Score:\s*(\d+)/i) || (details.match && details.match.match(/Value:\s*`(\d+)'/));
        if (scoreMatch) {
          anomalyScore = parseInt(scoreMatch[1], 10);
        }
        continue;
      }

      // Skip generic boundary and threshold rules
      const isMetaRule = ["949110", "959100", "980130", "901", "905"].some(m => ruleId.startsWith(m));
      if (isMetaRule) continue;

      // Assign weight: Attack families have highest priority
      let weight = 10;
      if (ruleId.startsWith("942")) weight = 100; // SQLi
      else if (ruleId.startsWith("941")) weight = 95; // XSS
      else if (ruleId.startsWith("932")) weight = 90; // RCE
      else if (ruleId.startsWith("930")) weight = 85; // LFI
      else if (ruleId.startsWith("944")) weight = 80; // Log4Shell / Deser
      else if (ruleId.startsWith("934")) weight = 75; // SSRF
      else if (ruleId.startsWith("931")) weight = 70; // RFI
      else if (ruleId.startsWith("913")) weight = 60; // Scanner
      else if (ruleId.startsWith("921")) weight = 40; // Protocol Attack
      else if (ruleId.startsWith("920")) weight = 20; // Protocol RFC

      // ModSecurity severity: "2" = Critical, "3" = Error, "4" = Warning, "5" = Notice
      const sevNum = parseInt(details.severity || "4", 10);
      const sevBonus = Math.max(0, 10 - sevNum * 2);

      candidateRules.push({
        ruleId,
        message: text,
        severity: details.severity || "4",
        file: details.file || "",
        lineNumber: details.lineNumber || "",
        data: details.data || "",
        tags: details.tags || [],
        totalWeight: weight + sevBonus
      });
    }

    if (candidateRules.length > 0) {
      candidateRules.sort((a, b) => b.totalWeight - a.totalWeight);
      primaryRule = candidateRules[0];
    }

    if (!primaryRule && messages.length > 0) {
      primaryRule = {
        ruleId: messages[0].details?.ruleId || "CRS-GENERIC",
        message: messages[0].message || "OWASP CRS Rule Match",
        severity: messages[0].details?.severity || "4",
        data: messages[0].details?.data || "",
        tags: messages[0].details?.tags || []
      };
    }

    // Determine category from tags or ruleId
    const tagsArr = Array.from(allTags);
    let category = "Web Anomaly";
    let mitreId = "T1190";

    if (tagsArr.includes("attack-sqli") || (primaryRule && primaryRule.ruleId.startsWith("942"))) {
      category = "SQL Injection";
      mitreId = "T1190";
    } else if (tagsArr.includes("attack-xss") || (primaryRule && primaryRule.ruleId.startsWith("941"))) {
      category = "Cross-Site Scripting (XSS)";
      mitreId = "T1059.007";
    } else if (tagsArr.includes("attack-rce") || (primaryRule && primaryRule.ruleId.startsWith("932"))) {
      category = "Remote Command Injection (RCE)";
      mitreId = "T1059";
    } else if (tagsArr.includes("attack-lfi") || (primaryRule && primaryRule.ruleId.startsWith("930"))) {
      category = "Path Traversal / LFI";
      mitreId = "T1083";
    } else if (tagsArr.includes("attack-rfi") || (primaryRule && primaryRule.ruleId.startsWith("931"))) {
      category = "Remote File Inclusion (RFI)";
      mitreId = "T1190";
    } else if (tagsArr.includes("attack-protocol") || (primaryRule && primaryRule.ruleId.startsWith("920"))) {
      category = "HTTP Protocol Violation";
      mitreId = "T1190";
    } else if (primaryRule && primaryRule.ruleId.startsWith("913")) {
      category = "Scanner / Automated Recon";
      mitreId = "T1595";
    }

    // Determine normalized severity
    let severity = "LOW";
    if (anomalyScore >= 20 || (primaryRule && primaryRule.severity === "2")) {
      severity = "CRITICAL";
    } else if (anomalyScore >= 10 || isBlocked) {
      severity = "HIGH";
    } else if (anomalyScore >= 5) {
      severity = "MEDIUM";
    }

    // Sanitized copy of transaction for forensics (redact sensitive auth tokens, passwords, cookies)
    const sanitizedRaw = JSON.parse(JSON.stringify(tx));
    if (sanitizedRaw.request?.headers) {
      for (const h of Object.keys(sanitizedRaw.request.headers)) {
        if (["cookie", "authorization", "x-api-key", "set-cookie", "proxy-authorization"].includes(h.toLowerCase())) {
          sanitizedRaw.request.headers[h] = "***REDACTED***";
        }
      }
    }
    if (sanitizedRaw.request?.body && typeof sanitizedRaw.request.body === "string") {
      // Redact password fields in body
      sanitizedRaw.request.body = sanitizedRaw.request.body.replace(/(password|passwd|secret|token|api_key)=[^&]+/gi, "$1=***REDACTED***");
    }

    let timestampIso = new Date().toISOString();
    if (tx.time_stamp) {
      try {
        const d = new Date(tx.time_stamp);
        if (!isNaN(d.getTime())) timestampIso = d.toISOString();
      } catch (e) {}
    }

    return {
      transactionId: String(tx.unique_id),
      timestamp: timestampIso,
      clientIp: socketClientIp,
      simulatedClientIp,
      simulatedSessionId,
      method: tx.request?.method || "GET",
      uri: tx.request?.uri || "/",
      httpCode,
      action,
      blocked: isBlocked,
      anomalyScore,
      primaryRuleId: primaryRule ? `OWASP-CRS-${primaryRule.ruleId}` : null,
      primaryRuleMsg: primaryRule ? primaryRule.message : null,
      category,
      mitreId,
      severity,
      tags: tagsArr,
      messages: messages.map(m => ({
        ruleId: m.details?.ruleId,
        message: m.message,
        data: m.details?.data,
        severity: m.details?.severity
      })),
      rawTransaction: sanitizedRaw,
      eventSource: "OFFICIAL_CRS"
    };
  }

  /**
   * Create or correlate genuine CRS event with Incident Command.
   * Preserves authentic CRS evidence without fabricating application vulnerability assertions.
   */
  async dispatchCrsIncident(event, wafEventRecord) {
    const primaryId = event.primaryRuleId || "OWASP-CRS-GENERIC";
    const ruleMsg = event.primaryRuleMsg || event.category;
    const ipLabel = event.simulatedClientIp 
      ? `${event.clientIp} (Simulation Identity: ${event.simulatedClientIp})`
      : event.clientIp;

    const title = `[OFFICIAL CRS] ${event.category} (${primaryId}) from ${event.simulatedClientIp || event.clientIp}`;
    const description = `The Official OWASP Core Rule Set Engine intercepted a request on ${event.method} ${event.uri}.
WAF Transaction ID: ${event.transactionId}
Primary Rule: ${primaryId} - ${ruleMsg}
Action Taken: ${event.action} (HTTP Status: ${event.httpCode})
Inbound Anomaly Score: ${event.anomalyScore}/5 threshold
Engine: ModSecurity v3.0.17 / Nginx 1.30.6 (OWASP_CRS/4.30.0)
Client IP: ${ipLabel}
Matched Signatures: ${event.messages.map(m => m.ruleId).filter(Boolean).join(", ")}.`;

    const playbook = {
      summary: `OWASP Core Rule Set matched incoming request pattern on ${event.uri}.`,
      rootCause: `Rule ${primaryId} triggered by request pattern: "${event.messages[0]?.data || 'Input match'}". (Note: This indicates a signature match against request input; it does not verify application exploitability.)`,
      immediateAction: event.blocked
        ? `Request was dropped by WAF with HTTP 403 Forbidden. Traffic did not reach the protected demo application.`
        : `Request was allowed with anomaly score ${event.anomalyScore}. Review anomaly score threshold if blocking is desired.`,
      codeRemediation: `Inspect application endpoint ${event.uri} and verify strict parameter validation, parameterized SQL statements, or contextual HTML encoding are in place.`,
      mitreInfo: { id: event.mitreId, tactic: "Initial Access", name: event.category },
      ruleId: primaryId,
      attackerIp: event.simulatedClientIp || event.clientIp,
      wafTransactionId: event.transactionId
    };

    const incidentData = {
      title,
      description,
      severity: event.severity,
      status: "OPEN",
      assignedTo: "OWASP-CRS-Engine",
      threatType: event.category,
      mitreTechnique: event.mitreId,
      playbook,
      extractedPayload: event.messages[0]?.data || event.uri,
      confidence: "HIGH (Deterministic Official OWASP CRS)",
      eventSource: "OFFICIAL_CRS",
      wafTransactionId: event.transactionId,
      payload: {
        rawLog: `${event.method} ${event.uri} HTTP/1.1\nHost: localhost:8080\nClient-IP: ${event.clientIp}\nSimulated-IP: ${event.simulatedClientIp || 'None'}\nHTTP-Code: ${event.httpCode}\nCRS-Anomaly-Score: ${event.anomalyScore}`,
        method: event.method,
        path: event.uri,
        ip: event.simulatedClientIp || event.clientIp,
        ruleId: primaryId,
        threatScore: Math.min(100, Math.max(50, event.anomalyScore * 5 || 75)),
        wafEventId: wafEventRecord ? wafEventRecord.id : null,
        transactionId: event.transactionId
      }
    };

    try {
      const created = await incidentService.createIncident(incidentData);
      if (this.io) {
        this.io.emit("incident_created", created);
        this.io.emit("dashboard_update_needed");
      }
      return created;
    } catch (err) {
      console.error("[CRS-INGESTION] Failed to create incident:", err.message);
      return null;
    }
  }

  /**
   * Reconcile any eligible WAF events that were persisted but missed campaign correlation
   */
  async recoverPendingEvents() {
    const stats = await localDb.getCampaignStats();
    if (stats.unlinkedEligibleEvents > 0) {
      const pendingBefore = stats.unlinkedEligibleEvents;
      console.log(`[CRS-INGESTION] Initiating correlation recovery for ${pendingBefore} unlinked eligible events...`);
      const res = localDb.reconcileDatabaseCampaigns(false);
      this.ingestionStatus.pendingRecovery = false;
      this.ingestionStatus.pendingRecoveryCount = 0;
      return {
        ...res,
        recovered: Math.max(0, pendingBefore - (res.unlinkedCount || 0))
      };
    }
    return { success: true, recovered: 0 };
  }

  /**
   * Return comprehensive status separating Gateway health from Ingestion health.
   */
  getStatus() {
    return {
      gateway: { ...this.gatewayHealth },
      ingestion: {
        ...this.ingestionStatus,
        logExists: fs.existsSync(this.logPath),
        logSize: fs.existsSync(this.logPath) ? fs.statSync(this.logPath).size : 0,
        readOffset: this.lastOffset
      },
      versions: {
        crsVersion: "OWASP_CRS/4.30.0",
        crsSetupVersion: "4300",
        modsecVersion: "ModSecurity v3.0.17",
        nginxVersion: "nginx/1.30.6",
        upstreamRuleFiles: 27,
        upstreamSecRulesCount: 675,
        paranoiaLevel: 1,
        inboundAnomalyThreshold: 5
      }
    };
  }
}

const crsIngestionService = new CrsIngestionService();
module.exports = crsIngestionService;
